import{_ as i,o,c as t,ag as r}from"./chunks/framework.DzGOF12C.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Phenomenology/07-Midterm-Review.md","filePath":"philosophy/Phenomenology/07-Midterm-Review.md"}'),n={name:"philosophy/Phenomenology/07-Midterm-Review.md"};function s(g,l,a,e,u,h){return o(),t("div",null,[...l[0]||(l[0]=[r('<h2 id="_1-현상학의-기획" tabindex="-1">1. 현상학의 기획 <a class="header-anchor" href="#_1-현상학의-기획" aria-label="Permalink to &quot;1. 현상학의 기획&quot;">​</a></h2><h3 id="_1-1-당시-시대비판" tabindex="-1">1.1 당시 시대비판 <a class="header-anchor" href="#_1-1-당시-시대비판" aria-label="Permalink to &quot;1.1 당시 시대비판&quot;">​</a></h3><ol><li><strong>독일관념론</strong>: 인식의 근거를 세계의 근거로 확장, 근거가 부족함. 자연주의와 역사주의에 동기를 불어넣음 — 사변적 반발로 자연주의, 상대주의적 관점으로 역사주의.</li><li><strong>자연주의</strong>: 모든 것을 자연주의적으로 환원하려는 시도. 논리적 법칙은 자연법칙으로 환원될 수 없음. 자연과학으로 설명되지 않는 것을 무리하게 포섭하려 함. 가령 어떤 논리 체계를 담당하는 자연적 부분이 없더라도 그 논리 체계는 참임.</li><li><strong>역사주의</strong>: 학문의 객관성을 상실하게 함. 어떠한 역사적 배경도 그것을 정당화해주지 않음. 가령 피타고라스 정리를 발견하게 한 역사적 동기가 그 정리를 정당화해주지 않음.</li><li><strong>형이상학적 관념론과 구별점</strong>: 모든 존재의 근원이 의식이라는 것이 아니라, 모든 인식의 근원이 의식임.</li><li><strong>환원주의와 구별점</strong>: 의식에 대한 탐구만 정당한 것이 아니라, 그것이 토대를 제공할 수 있음.</li><li><strong>상대주의와 구별점</strong>: 진리가 의식에 상대적이라는 것이 아니라, 진리가 의식에 나타나는 방식과 구조를 탐구해야 함.</li></ol><h3 id="_1-2-현상학의-두-가지-속성" tabindex="-1">1.2 현상학의 두 가지 속성 <a class="header-anchor" href="#_1-2-현상학의-두-가지-속성" aria-label="Permalink to &quot;1.2 현상학의 두 가지 속성&quot;">​</a></h3><ul><li><strong>인식적 절대성</strong>: 데카르트의 방식대로, 직접적으로 의식되는 것은 의심될 수 없음.</li><li><strong>인식적 근원성</strong>: 칸트의 방식대로, 모든 것은 의식으로부터 정당화됨.</li></ul><h2 id="_2-기본-개념" tabindex="-1">2. 기본 개념 <a class="header-anchor" href="#_2-기본-개념" aria-label="Permalink to &quot;2. 기본 개념&quot;">​</a></h2><p><strong>반성</strong>: 스스로 의식에 대해 직접적으로 관찰하는 것.</p><ol><li><strong>의식</strong>: 어떤 것을 느끼거나 경험하는 것</li><li><strong>대상</strong>: 의식에 나타나는 것</li><li><strong>노에시스, 노에마</strong>: 의식에 대한 것, 대상에 대한 것</li><li><strong>지향성</strong>: 어떤 것에 대한 것이라는 속성</li><li><strong>현상학적 환원</strong>: 실제 세계에서 그것이 나타나는 의식과 현상으로 눈을 돌림</li><li><strong>에포케</strong>: 판단 중지. 자연적 속성들에 괄호를 치고 현상학적인 것에 주목</li><li><strong>현상학적 환원 종류 3가지</strong><ul><li>데카르트적 환원: 확실하지 않은 것들에 대해 판단 중지하고 확실한 것으로 눈을 돌림</li><li>심리학적 환원: 심리학적인 요소인 물리학적·생물학적 요소를 차단하고 순수한 의식으로 눈을 돌림</li><li>생활세계적 환원: 학문을 통해 나타나는 세계에서 생활세계적 현상으로 눈을 돌림</li></ul></li><li><strong>현상학적 반성</strong>: 자기 의식에 대한 직접적인 관찰</li><li><strong>본질</strong>: 그것이 그것이기 위해 필연적으로 가져야 하는 속성</li><li><strong>형상적 환원</strong>: 다른 속성들을 배제하고 형상에 주목하는 것</li><li><strong>본질 직관</strong>: 대상을 여러 모습으로 바꿔가면서 그것의 본질을 찾는 것</li><li><strong>의미</strong>: 대상이 나에게 나타나는 방식</li><li><strong>정립</strong>: 대상에 대한 태도</li><li><strong>직관</strong>: 대상을 인식하는 것</li><li><strong>직관 종류 4개</strong>: 지각, 예상, 회상, 상상 <ul><li>지각: 대상을 지금 여기 있는 것으로 직관</li><li>예상: 대상을 언젠가 있을 것으로 직관</li><li>회상: 대상이 어딘가 있는 것으로 직관</li><li>상상: 대상이 없는 것으로 직관</li></ul></li><li><strong>지향 체계</strong>: 지향을 통해 기대를 생성하고, 이는 충족과 실망으로 이어짐</li><li><strong>지향 개념</strong>: 어떤 것이 직관될 것이라는 기대</li><li><strong>명증</strong>: 정립의 정당화, 또는 정당성</li><li><strong>파악</strong>: 어떤 것을 경험하면서 또 다른 것을 경험함</li><li><strong>구성</strong>: 어떤 대상에 대한 인식이 만들어짐</li><li><strong>휠레</strong>: 감각 자료</li></ol><h2 id="_3-지각" tabindex="-1">3. 지각 <a class="header-anchor" href="#_3-지각" aria-label="Permalink to &quot;3. 지각&quot;">​</a></h2><ol><li><strong>지각 (넓은 의미, 좁은 의미)</strong>: 사물을 인식하는 것 — 넓은 의미는 대상을 직접적으로 인식, 좁은 의미는 사물을 직접적으로 인식</li><li><strong>사물</strong>: 시공간적, 인과적 속성을 지니는 것</li><li><strong>작용</strong>: 지향성을 지니는 의식</li><li><strong>회상, 예상</strong>: 간접 명증적 직관</li><li><strong>상상</strong>: 비명증적 직관</li><li><strong>파악</strong>: 어떤 것을 경험하면서 또 다른 것으로 경험, 다른 것으로 해석함. 자료들이 사물과 사물의 속성으로 인식됨.</li><li><strong>지평</strong>: 어떤 것이 의식될 때 함께 의식되는 모든 것 <ul><li>내적 지평: 어떤 대상의 부분과 내적 속성</li><li>외적 지평: 환경과 외적 속성</li></ul></li><li><strong>몸 (감각 두 개)</strong><ul><li>운동감각: 신체의 움직임에 대한 감각, 고유감각 포함</li><li>고유감각: 몸 내부에 대한 감각</li></ul></li><li><strong>기대</strong>: 어떤 것이 경험될 것이라는 믿음</li><li><strong>지각의 구조</strong>: 시간구성, 공간구성, 인과구성 <ul><li>시간 구성: 지속 — 순간적인 감각적 성질이 지속적인 감각적 성질로 파악</li><li>공간 구성: 환상 — 지속적인 감각적 성질들이 하나의 공간적 형태로 파악</li><li>인과 구성: 사물 — 공간적 형태가 하나의 인과적 실체로 파악</li></ul></li></ol><h2 id="_4-판단" tabindex="-1">4. 판단 <a class="header-anchor" href="#_4-판단" aria-label="Permalink to &quot;4. 판단&quot;">​</a></h2><ol><li><strong>판단</strong>: 사실에 대한 의식 <ul><li>감각적 경험이 없으면 판단이 일어날 수 없음</li><li>감각적 경험으로부터만 직관적이고 명증적인 판단이 일어날 수 있음</li></ul></li><li><strong>추상적 대상</strong>: 시공간적 속성을 넘어서 있는 대상 <ul><li>직관/비직관, 명증/비명증</li><li>종합이 판단의 근원</li></ul></li><li><strong>사실</strong>: 사태. &quot;어떤 것은 ~한 상태이다&quot;로 표현</li><li><strong>사실 인식 단계</strong><ul><li>전체와 부분의 종합: 전 단계</li><li>명시화: 전체를 인식하면서 그것의 부분의 속성에 동시에 주목</li><li>사실 인식: 그것을 사실로 받아들임, 기체-속성 관계를 인식</li></ul></li><li><strong>집합</strong>: 특정한 대상들의 모음</li><li><strong>집합 인식 단계</strong><ul><li>연언의 종합: 대상들을 하나하나 함께 주목함</li><li>집합 인식: 결합된 집합 자체를 인식함</li></ul></li><li><strong>보편자</strong>: 여러 대상들이 동시에 가지는 보편적 속성</li><li><strong>보편자 인식 단계</strong><ul><li>유사한 대상들의 종합: 유사한 대상에 대한 경험이 서로 합치됨</li><li>개별적 판단: 유사한 대상들 각각에 대해 그것이 성질 P를 갖는다고 판단함</li><li>보편자 인식: 개별자를 넘어 P의 보편자 자체를 인식함</li></ul></li></ol><h2 id="_5-의식의-심층" tabindex="-1">5. 의식의 심층 <a class="header-anchor" href="#_5-의식의-심층" aria-label="Permalink to &quot;5. 의식의 심층&quot;">​</a></h2><ol><li><strong>현상학적 시간</strong>: 대상들이 현재, 과거, 미래의 방식으로 의식되는 방식</li><li><strong>촉발</strong>: 대상이 주체의 행위를 자극함</li><li><strong>현상학적 시간의 3가지 층위</strong><ul><li>일상적/근원적 지향 층위: 지각, 회상, 예상</li><li>심층적 내적 시간의식 층위: 인상, 파지, 예지 <ul><li>인상: 감각 자료들이 바로 지금 경험됨</li><li>파지: 방금 경험된 자료들이 여전히 의식됨</li><li>예지: 아직 경험되지 않은 자료들이 앞서 의식됨</li></ul></li></ul></li><li><strong>파지·예지의 속성</strong>: 비직관적</li><li><strong>내적 의식</strong>: 의식에 관한 의식</li><li><strong>외적 의식</strong>: 의식 바깥에 대한 의식</li><li><strong>선반성적 자기 의식</strong>: 내적 의식으로서 의식이 생기기 전, 즉 반성이 이뤄지기 전에 이미 있는 의식에 대한 의식 → 내적 시간의식으로 연결됨</li><li><strong>촉발의 방식 2개</strong><ul><li>융합: 질적으로 같은 자료들이 모여 촉발함</li><li>대조: 질적으로 서로 다른 자료들이 분리되어 촉발함</li><li>촉발하는 자료는 촉발하지 않은 자료들의 융합과 대조의 산물 → 현상학적 무의식에 대한 탐구가 가능해짐</li></ul></li><li><strong>파지·예지가 직관이 아닌 이유</strong>: 우리는 음을 들으면서 인상·파지·예지를 동시에 작동시킴. 파지와 예지가 직관(지금 경험되는 것)이라면 과거의 음과 미래의 음을 현재의 음과 함께 들어야 하지만 실제로는 그렇지 않음. 따라서 파지·예지는 비직관적 속성을 지님.</li></ol>',14)])])}const c=i(n,[["render",s]]);export{_ as __pageData,c as default};
